function importJournal(payload){
  if(payload?.format!=='cinema500-journal-v1'||!Array.isArray(payload.titles)||payload.titles.length>10000)throw Error('invalid_backup');
  const nextDiscovery=payload.discovery===undefined?discoverySettings:discovery.mergeSettings(discoverySettings,payload.discovery),nextMemory=new Map(titleMemory);
  for(const p of payload.titles){if(p&&!nextMemory.has(p.id)&&p.titleData){const row=live.title(p.titleData,false);if(row.id!==p.id)throw Error('invalid_entry');nextMemory.set(p.id,row);}}
  const known=new Set(nextMemory.keys()),ids=new Set();
  const entries=payload.titles.filter(p=>{if(!p||!known.has(p.id)||ids.has(p.id)||!['none','seen','watchlist'].includes(p.status)||(p.rating!==undefined&&p.rating!==null&&(!Number.isInteger(p.rating)||p.rating<1||p.rating>10))||(p.favorite!==undefined&&typeof p.favorite!=='boolean')||(p.note!==undefined&&(typeof p.note!=='string'||p.note.length>2000))||(p.watchedOn!==undefined&&p.watchedOn!==null&&!validWatchDate(p.watchedOn)))throw Error('invalid_entry');ids.add(p.id);return true});
  const nextSeen=new Set(seen),nextWanted=new Set(wanted),nextPrefs=new Map(preferences);let added=0;
  for(const p of entries){let changed=false;if(!nextSeen.has(p.id)&&!nextWanted.has(p.id)){if(p.status==='seen'){nextSeen.add(p.id);changed=true}if(p.status==='watchlist'){nextWanted.add(p.id);changed=true}}const prior=nextPrefs.get(p.id)||{id:p.id,rating:null,favorite:false};const value={id:p.id,rating:prior.rating||p.rating||null,favorite:prior.favorite||p.favorite||false,note:prior.note||p.note||'',watchedOn:prior.watchedOn||p.watchedOn||null};if(value.rating!==prior.rating||value.favorite!==prior.favorite||value.note!==(prior.note||'')||value.watchedOn!==(prior.watchedOn||null)){nextPrefs.set(p.id,value);changed=true}if(changed)added++;}
  const archiveIds=new Set([...nextSeen,...nextWanted,...nextPrefs.keys()]);
  const writes=[['cinema-seen',[...nextSeen]],['cinema-wanted',[...nextWanted]],['cinema-preferences',[...nextPrefs.values()]],['cinema-discovery',nextDiscovery],['cinema-title-archive',[...archiveIds].map(id=>nextMemory.get(id)).filter(Boolean)]].map(([key,value])=>[journalKey(key),value]);
  const before=writes.map(([key])=>[key,localStorage.getItem(key)]);
  try{for(const [key,value] of writes)localStorage.setItem(key,JSON.stringify(value));}catch(error){for(const [key,value] of before){try{value===null?localStorage.removeItem(key):localStorage.setItem(key,value)}catch{}}throw error;}
  titleMemory=nextMemory;seen=nextSeen;wanted=nextWanted;preferences=nextPrefs;guestSeen=new Set(seen);guestWanted=new Set(wanted);guestPreferences=new Map(preferences);discoverySettings=nextDiscovery;stateVersion++;return added;
}
