  const node=$('#catalog-date'),state=liveNetworkFailed?'stale':live.freshness(catalogueInfo);
  const date=new Date(catalogueInfo.retrievedAt).toLocaleString('fa-IR',{month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'});
  node.dataset.freshness=state;
  node.textContent=(state==='current'?'آخرین به‌روزرسانی از IMDb: ':state==='snapshot'?'نسخهٔ اولیهٔ فهرست: ':'آخرین نسخهٔ ذخیره‌شده: ')+date+' · بررسی خودکار هر ساعت'+(pendingCatalogue?' · نسخهٔ تازه آماده است':'');
