function applyPendingCatalogue(){
  if(pendingCatalogue&&!isOverlayOpen()){const next=pendingCatalogue;pendingCatalogue=null;applyLiveCatalogue(next);}
}
async function refreshLiveCatalogue(force=false){
  if(typeof window.fetch!=='function'||liveBusy||(!force&&document.visibilityState==='hidden'))return;
  const stamp=Date.now();if(!force&&stamp-liveAttemptAt<5*60*1000)return;if(force&&stamp-liveAttemptAt<10000){toast('چند ثانیه صبر کن و دوباره بزن.');return;}
  liveAttemptAt=stamp;liveBusy=true;renderCatalogStatus();
  const controller=typeof AbortController==='function'?new AbortController():null,timer=controller?setTimeout(()=>controller.abort(),15000):null;
  try{
    const response=await window.fetch('./live-catalogue.json?check='+Math.floor(stamp/300000),{cache:'no-cache',credentials:'omit',...(controller?{signal:controller.signal}:{})});
    if(!response.ok)throw Error('catalogue_unavailable');
    const next=live.validate(await response.json());liveNetworkFailed=false;
    if(pendingCatalogue&&!live.fresher(next,pendingCatalogue))return;
    if(!live.fresher(next,catalogueInfo)){if(force)toast('فهرست جدیدتری در دسترس نیست.');return;}
    if(isOverlayOpen()&&next.version!==catalogueInfo.version){pendingCatalogue=next;if(force)toast('فهرست تازه آماده است؛ این پنجره رو که ببندی، نمایش داده می‌شه.');}
    else {const changed=applyLiveCatalogue(next);if(force)toast(changed?'فهرست به‌روز شد.':'نسخهٔ تازه‌تری نیست؛ فهرست هر ساعت خودکار بررسی می‌شه.');}
  }catch{liveNetworkFailed=true;if(force)toast('به‌روزرسانی دریافت نشد؛ فعلاً آخرین فهرست ذخیره‌شده رو می‌بینی.');}
  finally{if(timer)clearTimeout(timer);liveBusy=false;renderCatalogStatus();}
}
function scheduleCatalogueCheck(){
  if(typeof window.fetch!=='function')return;clearTimeout(liveTimer);
  liveTimer=setTimeout(()=>{refreshLiveCatalogue();scheduleCatalogueCheck()},5*60*1000);
}
