function stepHero(direction){const frames=backdropIds.map(id=>findTitle(id)).filter(Boolean);if(frames.length<2)return;const current=frames.findIndex(a=>a.id===selectedId);setAmbient(frames[(Math.max(0,current)+direction+frames.length)%frames.length]);}
